import { foundationEquipmentCatalogIssues } from "./foundationEquipmentBindings";
import { foundationWallCapCatalogIssues } from "./wallCapCalculator";
import { foundationWallCatalogIssues } from "./wallCalculator";
// CMP-A08: the catalog price basis lives on the normalization boundary —
// finite, nonnegative; a recorded 0 is a deliberate free price, absent or
// malformed is unpriced (never laundered to 0 or guessed).
import { inventoryNonnegativeNumber } from "@/components/masterInventory/inventoryNormalization";

// ─── Catalog lifecycle + price classification (O-009 / CMP-A09) ────────────
//
// The catalog rows the estimator sees arrive through a filtered load
// (`show_in_foundation: true` on FoundationInventory, `is_active: true` on
// LaborServiceInventory) — except labor-service supplier rows, which are
// merged client-side AFTER the query and can still carry
// `show_in_foundation: false`, and any row a caller passes unfiltered. A
// project reference can therefore resolve four ways, previously lumped:
//   • the row is present and current            → usable,
//   • the row is present but marked INACTIVE    → was picked before
//     deactivation; the picker hides it now (was reported as nothing),
//   • the row is present but marked DELETED     → soft-deleted tombstone
//     still in the loaded list,
//   • the row is ABSENT                         → deleted or filtered out;
//     we cannot tell which from this list, so the issue says both.
// Price basis classifies the same way: a recorded finite nonnegative price
// is "priced" (0 = deliberately free), anything else is "unpriced" — the
// ported `|| 0` fallbacks laundered unpriced into a silent free.

const INACTIVE_STATUS_VALUES = new Set([
  "inactive", "disabled", "archived", "discontinued", "retired", "deactivated",
]);
const DELETED_STATUS_VALUES = new Set(["deleted", "removed", "purged"]);

// Row lifecycle class: "deleted" tombstones win over "inactive" flags; a row
// carrying neither is "active". Schemaless flags from every catalog source
// are honored — FoundationInventory's picker flag (`show_in_foundation`),
// LaborServiceInventory's `is_active`, and generic `active`/`archived`/
// `status`/`deleted_at` markers an import or admin surface may write.
export function foundationCatalogRowAvailability(row) {
  if (!row || typeof row !== "object") return "deleted";
  const status = typeof row.status === "string" ? row.status.trim().toLowerCase() : "";
  if (row.deleted === true || row.is_deleted === true || row.deleted_at != null
    || DELETED_STATUS_VALUES.has(status)) return "deleted";
  if (row.is_active === false || row.active === false
    || row.archived === true || row.is_archived === true || row.disabled === true
    || row.show_in_foundation === false || INACTIVE_STATUS_VALUES.has(status)) return "inactive";
  return "active";
}

// Consumed catalog price basis: "unpriced" (absent/malformed/negative — the
// boundary returns null), "free" (a recorded explicit 0), else "priced".
export function foundationCatalogPriceClass(value) {
  const number = inventoryNonnegativeNumber(value);
  if (number === null) return "unpriced";
  return number === 0 ? "free" : "priced";
}

// A custom override is "authored" exactly when the calculator consumes it —
// `value !== null && !== undefined` mirrors the calcItemCost `??` picks.
const authoredOverride = (value) => value !== undefined && value !== null;
// The item's `|| "#4"` / picker fallbacks treat every falsy value as
// unselected; mirror that (an authored blank string still defaults).
const authoredSelection = (value) => value !== undefined && value !== null && value !== "";

export function foundationItemCatalogIssues(item, inventory = [], index = 0) {
  const issues = [];
  const add = (field, id, code, message) => issues.push({
    kind: "foundation", index, componentId: item.component_id ?? null, field,
    inventoryId: id ?? null, code,
    message: `Foundation ${index + 1}: ${message}`,
  });
  const selected = id => id !== undefined && id !== null && id !== "";
  // Selected-id check: absent → unavailable (deleted or deactivated — the
  // loaded catalog can't tell them apart); found → type, then lifecycle,
  // then the consumed price basis. Deliberate free (recorded 0) never flags.
  const check = (field, types, label, { unassigned = null, priceBasis = null } = {}) => {
    const id = item[field];
    if (!selected(id)) {
      if (unassigned) add(field, null, "catalog_item_unassigned", unassigned);
      return;
    }
    const row = inventory.find(record => record.id === id);
    if (!row) {
      add(field, id, "catalog_item_unavailable",
        `${label} is unavailable — the catalog row may have been deleted or deactivated`);
      return;
    }
    if (!types.includes(row.material_type)) {
      add(field, id, "catalog_item_type_mismatch", `${label} is the wrong catalog type`);
      return;
    }
    const availability = foundationCatalogRowAvailability(row);
    if (availability !== "active") {
      add(field, id, availability === "deleted" ? "catalog_item_deleted" : "catalog_item_inactive",
        availability === "deleted"
          ? `${label} is marked deleted in the catalog — pick a replacement`
          : `${label} is inactive in the catalog — reactivate it or pick a replacement`);
      return;
    }
    const basis = priceBasis?.(row);
    if (basis && foundationCatalogPriceClass(row[basis]) === "unpriced") {
      add(field, id, "catalog_item_unpriced",
        `${label} has no recorded ${basis} — a missing price is not a free material`);
    }
  };
  // Concrete is consumed by every item: an unassigned selection rides the
  // first supplier's delivery catalog or prices material at $0, never an
  // authored free — flag it like the sibling pickers already do.
  check("selected_concrete_id", ["bagged_concrete", "concrete_service"], "the selected concrete catalog material", {
    unassigned: "select a concrete catalog material — unassigned concrete rides the first supplier's delivery mix or prices at $0",
    // Item-level bag pricing consumes cost_per_unit; a service row's mixes
    // and fees are the delivery scan's own checks, never duplicated here.
    priceBasis: row => (row.material_type === "bagged_concrete" && !authoredOverride(item.custom_concrete_cost_per_cy)
      ? "cost_per_unit" : null),
  });
  if (item.include_forming) check("selected_forming_id", ["forming_material"], "the selected forming catalog material", {
    // An authored custom rate replaces the catalog basis entirely; the row
    // is then consumed for nothing and unassigned/unpriced stay silent.
    unassigned: !authoredOverride(item.custom_forming_rate)
      ? "select a forming catalog material or record a custom forming rate"
      : null,
    priceBasis: row => (!authoredOverride(item.custom_forming_rate) ? "cost_per_unit" : null),
  });
  // Versioned items price steel through their explicit reinforcement_material
  // basis — a catalog basis needs exactly one current rebar-typed row; the
  // legacy rebar_size lookup below does not apply to them.
  if (item.reinforcement_calculation_version != null && item.reinforcement_calculation_version !== 1) {
    if (item.reinforcement_calculation_version === 2 && item.include_rebar && item.reinforcement_material?.kind === "catalog") {
      const id = item.reinforcement_material.inventory_id;
      const matches = selected(id) ? inventory.filter(row => row.id === id) : [];
      if (matches.length !== 1 || matches[0].material_type !== "rebar") {
        add("reinforcement_material.inventory_id", id,
          !selected(id) ? "catalog_item_unassigned" : matches.length > 1 ? "catalog_item_ambiguous" : "catalog_item_unavailable",
          !selected(id) ? "select a reinforcement catalog material"
            : matches.length > 1 ? "the selected reinforcement catalog ID is ambiguous; refresh the catalog"
            : "the selected reinforcement catalog material is unavailable — it may have been deleted or deactivated");
      } else {
        const availability = foundationCatalogRowAvailability(matches[0]);
        if (availability !== "active") {
          add("reinforcement_material.inventory_id", id,
            availability === "deleted" ? "catalog_item_deleted" : "catalog_item_inactive",
            availability === "deleted"
              ? "the selected reinforcement catalog material is marked deleted — pick a replacement"
              : "the selected reinforcement catalog material is inactive — reactivate it or pick a replacement");
        }
      }
    }
    return issues;
  }
  const manualRebar = hasFoundationCostSnapshot(item.custom_rebar_cost_per_ft) && item.custom_rebar_cost_per_ft >= 0;
  if (item.include_rebar && !manualRebar) {
    const field = item.foundation_type === "spread_foot" ? "rebar_size" : "pillar_rebar_size";
    const authoredSize = field === "rebar_size" ? item.rebar_size : item.pillar_rebar_size;
    // A pillar with no authored size silently consumes the catalog "#4"
    // default (the ported `pillar_rebar_size || '#4'` pick) — flag the
    // unassigned default whether or not a #4 row exists to consume.
    const defaulted = field === "pillar_rebar_size" && !authoredSize;
    const size = defaulted ? "#4" : authoredSize;
    const row = size ? inventory.find(record => record.material_type === "rebar" && record.rebar_size === size) : null;
    if (defaulted) {
      const rowState = row ? foundationCatalogRowAvailability(row) : null;
      add(field, row?.id ?? null, "catalog_item_unassigned_default", !row
        ? `no rebar size is selected and the catalog has no ${size} rebar default to consume — select a size`
        : rowState !== "active"
          ? `no rebar size is selected — the catalog ${size} default resolves to ${rowState === "inactive" ? "an inactive" : "a deleted"} row; pick a size explicitly`
          : `no rebar size is selected — the catalog ${size} default is consumed; pick a size explicitly`);
    } else if (!row) {
      add(field, null, size ? "catalog_item_unavailable" : "catalog_item_unassigned",
        size ? `rebar catalog size ${size} is unavailable — it may have been deleted or deactivated`
          : "select a rebar catalog size");
    } else {
      const availability = foundationCatalogRowAvailability(row);
      if (availability !== "active") {
        add(field, row.id, availability === "deleted" ? "catalog_item_deleted" : "catalog_item_inactive",
          availability === "deleted"
            ? `rebar catalog size ${size} is marked deleted — pick another size`
            : `rebar catalog size ${size} is inactive — reactivate it or pick another size`);
      } else if (!authoredOverride(item.custom_rebar_cost_per_ft)
        && foundationCatalogPriceClass(row.cost_per_unit) === "unpriced") {
        add(field, row.id, "catalog_item_unpriced",
          `rebar catalog size ${size} has no recorded cost_per_unit — a missing price is not a free material`);
      }
    }
  }
  return issues;
}

// Check catalog availability and the explicit wall-cap full-stock price basis.
export function foundationAssemblyCatalogIssues(project, inventory = []) {
  const issues = [];
  const check = (row, index, kind, field, label) => {
    const id = row[field];
    const assigned = (typeof id === "string" && id.trim() !== "")
      || (typeof id === "number" && Number.isFinite(id));
    if (!assigned) {
      issues.push({
        kind,
        index,
        componentId: row.component_id ?? row.id ?? null,
        field,
        inventoryId: null,
        code: "catalog_item_unassigned",
        message: `${label} ${index + 1}: select a catalog material.`,
      });
      return;
    }
    const match = inventory.find((record) => record.id === id);
    if (!match) {
      issues.push({
        kind,
        index,
        componentId: row.component_id ?? row.id ?? null,
        field,
        inventoryId: id,
        code: "catalog_item_unavailable",
        message: `${label} ${index + 1}: selected catalog material is unavailable — it may have been deleted or deactivated.`,
      });
      return;
    }
    const availability = foundationCatalogRowAvailability(match);
    if (availability !== "active") {
      issues.push({
        kind,
        index,
        componentId: row.component_id ?? row.id ?? null,
        field,
        inventoryId: id,
        code: availability === "deleted" ? "catalog_item_deleted" : "catalog_item_inactive",
        message: availability === "deleted"
          ? `${label} ${index + 1}: selected catalog material is marked deleted — pick a replacement.`
          : `${label} ${index + 1}: selected catalog material is inactive — reactivate it or pick a replacement.`,
      });
    }
  };
  for (const [index, pole] of (project?.poles || []).entries()) {
    check(pole, index, "pole", "pole_id", "Pole");
  }
  // Unassigned-default (CMP-A09): when the project names no concrete mix the
  // delivery scan silently consumes the first ready-mix supplier's catalog
  // '4000_ae' mix. Flag the unassigned default whenever a service supplier is
  // actually selected — the mix consumption itself stays the delivery scan's.
  if (!project?.project_concrete_type) {
    const firstServiceItem = (project?.items || []).find((item) => {
      const row = inventory.find((record) => record?.id === item?.selected_concrete_id);
      return row?.material_type === "concrete_service";
    });
    if (firstServiceItem) {
      issues.push({
        kind: "concrete_delivery",
        index: null,
        componentId: null,
        field: "project_concrete_type",
        inventoryId: firstServiceItem.selected_concrete_id ?? null,
        code: "catalog_item_unassigned_default",
        message: "Concrete delivery: no concrete mix is selected — the supplier's catalog default mix is consumed when concrete ships. Pick a mix explicitly.",
      });
    }
  }
  return [
    ...issues,
    ...foundationWallCatalogIssues(project?.walls || [], inventory),
    ...foundationWallCapCatalogIssues(project?.wall_caps || [], inventory),
    ...(project?.items || []).flatMap((item, index) => foundationItemCatalogIssues(item, inventory, index)),
    ...foundationEquipmentCatalogIssues(project?.selected_equipment || [], inventory),
  ];
}

// ─── Advisory classification audit (O-009 / CMP-A09) ────────────────────────
//
// Non-blocking mirror of the item scan: every catalog basis the item can
// consume, classified so downstream surfaces keep deliberate free ($0),
// unpriced (missing), implicit defaults, and inactive/deleted rows distinct
// instead of lumping them under "unavailable". Nothing here gates pricing —
// the blocking flags live in foundationItemCatalogIssues above.
export function foundationItemCatalogAudit(item, inventory = [], index = 0) {
  const record = item ?? {};
  const audit = [];
  const emit = (field, inventoryId, selection, availability, priceClass) => audit.push({
    kind: "foundation", index, componentId: record.component_id ?? null,
    field, inventoryId: inventoryId ?? null, selection, availability, priceClass,
  });
  const auditId = (field, { overrideAuthored = false, priceBasis = null, unconsumedClass = "unchecked" } = {}) => {
    const id = record[field];
    if (!authoredSelection(id)) {
      emit(field, null, "unassigned", "unassigned", overrideAuthored ? "override" : unconsumedClass);
      return;
    }
    const row = inventory.find((candidate) => candidate.id === id);
    if (!row) {
      emit(field, id, "authored", "missing", overrideAuthored ? "override" : unconsumedClass);
      return;
    }
    const availability = foundationCatalogRowAvailability(row);
    const basis = priceBasis?.(row);
    emit(field, id, "authored", availability,
      overrideAuthored ? "override"
        : basis ? foundationCatalogPriceClass(row[basis]) : unconsumedClass);
  };
  auditId("selected_concrete_id", {
    overrideAuthored: authoredOverride(record.custom_concrete_cost_per_cy),
    priceBasis: (row) => (row.material_type === "bagged_concrete" ? "cost_per_unit" : null),
    unconsumedClass: "deferred", // ready-mix prices ship through the delivery scan's mix/admix/fee checks
  });
  if (record.include_forming) {
    auditId("selected_forming_id", {
      overrideAuthored: authoredOverride(record.custom_forming_rate),
      priceBasis: () => "cost_per_unit",
      unconsumedClass: "unconsumed", // a missing/unassigned forming row consumes no catalog basis
    });
  }
  if (record.reinforcement_calculation_version != null && record.reinforcement_calculation_version !== 1) {
    if (record.reinforcement_calculation_version === 2 && record.include_rebar
      && record.reinforcement_material?.kind === "catalog") {
      auditId("reinforcement_material.inventory_id", { unconsumedClass: "deferred" });
    }
    return audit;
  }
  const manualRebar = hasFoundationCostSnapshot(record.custom_rebar_cost_per_ft) && record.custom_rebar_cost_per_ft >= 0;
  if (record.include_rebar && !manualRebar) {
    const field = record.foundation_type === "spread_foot" ? "rebar_size" : "pillar_rebar_size";
    const authoredSize = field === "rebar_size" ? record.rebar_size : record.pillar_rebar_size;
    const defaulted = field === "pillar_rebar_size" && !authoredSize;
    const size = defaulted ? "#4" : authoredSize;
    if (!size) {
      emit(field, null, "unassigned", "unassigned",
        authoredOverride(record.custom_rebar_cost_per_ft) ? "override" : "unconsumed");
    } else {
      const row = inventory.find((candidate) => candidate.material_type === "rebar" && candidate.rebar_size === size);
      emit(field, row?.id ?? null, defaulted ? "defaulted" : "authored",
        row ? foundationCatalogRowAvailability(row) : "missing",
        authoredOverride(record.custom_rebar_cost_per_ft) ? "override"
          : row ? foundationCatalogPriceClass(row.cost_per_unit) : "unconsumed");
    }
  }
  return audit;
}

// A missing snapshot is not evidence of a free material.
export function hasFoundationCostSnapshot(value) {
  return typeof value === "number" && Number.isFinite(value);
}

// Painting pricing-availability layer.
//
// Wraps calculatePaintingProject with strict finite-number input validation so
// a missing, malformed, or unusable pricing input can no longer silently
// become $0, a hidden default, or a dropped item edge. Mirrors the landed
// Foundation/Vinyl hardening convention:
//   - strict parsers (paintStrictNumber / paintSettingNumber / paintThicknessNumber,
//     owned by paintCalc so the calculator and the scanner resolve identically)
//   - structured issue records { kind, index, itemIndex, field, code, message, hold }
//   - Painting has no catalog entities — the shared Settings rows are the
//     priced surface, so settings issues are kind "paint_catalog" and hold the
//     whole project calc; authored item/project-field issues hold the affected
//     item's derived numbers and every aggregate those numbers feed.
//   - explicit 0 stays valid where the calculator treats it as a real
//     free/zero amount (rates, multipliers, hours, floors, costs); 0 is
//     invalid where the math divides or needs a real magnitude (coverage, the
//     paint mix ratio, the waste multiplier, the labor rate divisor, the
//     letter perimeter factor).
//   - raw rows are never mutated — the calculator reads the original records
//     exactly as PaintingEstimator has always passed them.
//
// Valid inputs take the exact same code path as before: the calc object the
// page receives for a clean project is bit-identical to today's result (plus
// __held / pricingUnavailable / issues metadata flags).

import {
  calculatePaintingProject,
  paintSettingNumber,
  paintSettingRecorded,
  paintStrictNumber,
  paintThicknessNumber,
} from "./paintCalc";

// ---------- issue records ----------
const issue = (kind, { index = null, itemIndex = null, field, code, message, hold }) => ({
  kind, index, itemIndex, field, code, message, hold,
});

// ---------- settings scan ----------
// Every Settings row the calculator prices from. [key, human, positive]
// positive: true  → recorded value must be > 0
// positive: false → recorded value must be finite and >= 0
const PRICED_SETTINGS = [
  ["default_labor_rate", "default labor rate ($/hr)", true],
  ["min_labor_hours", "minimum labor hours floor", false],
  ["min_paint_cost", "minimum paint cost floor", false],
  ["default_paint_supplies_per_sqft", "default paint supplies per sq ft", false],
  ["paint_cost_per_unit", "paint cost per unit", false],
  ["hardener_cost_per_unit", "hardener cost per unit", false],
  ["reducer_cost_per_unit", "reducer cost per unit", false],
  ["paint_mix_ratio", "paint mix ratio", true],
  ["hardener_mix_ratio", "hardener mix ratio", false],
  ["reducer_mix_ratio", "reducer mix ratio", false],
  ["mixed_paint_coverage_sqft_per_gallon", "mixed paint coverage (sq ft/gallon)", true],
  ["paint_waste_multiplier", "paint waste multiplier", true],
  ["fixed_paint_waste_gallons", "fixed paint waste (gallons)", false],
  ["paint_mask_rate_per_sqft", "paint mask material rate per sq ft", false],
  ["paint_mask_machine_cutting_rate_per_sqft", "paint mask machine cutting rate per sq ft", false],
  ["paint_mask_application_labor_rate_per_sqft", "paint mask application labor rate per sq ft", false],
  ["paint_mask_cutting_labor_rate_per_sqft", "paint mask cutting labor rate per sq ft", false],
  ["base_labor_hours_per_sqft", "base labor hours per sq ft", false],
  ["setup_time_labor_hours", "setup time (hours)", false],
  ["paint_mixing_labor_hours", "paint mixing labor hours per mix", false],
  ["color_change_setup_hours", "color change setup hours", false],
  ["paint_gun_cleaning_hours", "paint gun cleaning hours", false],
  ["one_side_paint_multiplier", "one-side paint multiplier", false],
  ["both_sides_paint_multiplier", "both-sides paint multiplier", false],
  ["additional_color_multiplier", "additional color multiplier", false],
  ["simple_complexity_multiplier", "simple complexity multiplier", false],
  ["moderate_complexity_multiplier", "moderate complexity multiplier", false],
  ["complex_complexity_multiplier", "complex complexity multiplier", false],
  ["letter_perimeter_factor", "letter perimeter factor", true],
];

const PAINT_UNITS = ["oz", "pint", "quart", "liter", "gallon"];
const TIER_SETTINGS = [
  ["panel_labor_tiers", "panel labor tiers"],
  ["complex_shapes_labor_tiers", "complex shape labor tiers"],
  ["lettering_labor_tiers", "lettering labor tiers"],
];

// Settings rows the calc prices from. Only recorded values can be broken —
// an absent row falls back to the documented module default by design, so it
// is never an issue. Every settings issue holds the whole project calc.
export function paintSettingIssues(settings = {}) {
  const issues = [];
  const add = (field, code, message) =>
    issues.push(issue("paint_catalog", { field, code, message, hold: "project" }));

  for (const [key, human, positive] of PRICED_SETTINGS) {
    if (!paintSettingRecorded(settings, key)) continue;
    const n = paintStrictNumber(settings[key]);
    if (n === null || (positive ? n <= 0 : n < 0)) {
      add(key, "paint_setting_unavailable",
        `Setting ${key}: record a finite, ${positive ? "positive" : "nonnegative"} ${human} in Painting Settings — the stored value cannot price this estimate`);
    }
  }

  // Liquid unit selectors — a recorded-but-unsupported unit resolves 0 in
  // costPerGallon (silently free); a missing unit next to a priced component
  // does the same.
  for (const [costKey, unitKey, human] of [
    ["paint_cost_per_unit", "paint_unit", "paint"],
    ["hardener_cost_per_unit", "hardener_unit", "hardener"],
    ["reducer_cost_per_unit", "reducer_unit", "reducer"],
  ]) {
    const unitRecorded = paintSettingRecorded(settings, unitKey);
    const unitValid = PAINT_UNITS.includes(settings?.[unitKey]);
    if (unitRecorded && !unitValid) {
      add(unitKey, "paint_liquid_unit_unavailable",
        `Setting ${unitKey}: select a supported ${human} unit (oz / pint / quart / liter / gallon) in Painting Settings`);
    } else if (!unitValid && (paintStrictNumber(settings?.[costKey]) ?? 0) > 0) {
      add(unitKey, "paint_liquid_unit_unavailable",
        `Setting ${unitKey}: set a ${human} unit — a recorded ${costKey} prices as $0 without one`);
    }
  }

  // Labor tier tables are JSON arrays of {min_quantity, max_quantity,
  // labor_multiplier}. Malformed JSON silently disables the whole table;
  // malformed row fields silently dead-window the tier or reprice it.
  for (const [key, human] of TIER_SETTINGS) {
    if (!paintSettingRecorded(settings, key)) continue;
    const raw = settings[key];
    let tiers = raw;
    if (!Array.isArray(tiers)) {
      try {
        const parsed = JSON.parse(raw || "[]");
        tiers = Array.isArray(parsed) ? parsed : null;
      } catch {
        tiers = null;
      }
    }
    if (tiers === null) {
      add(key, "paint_labor_tiers_unavailable",
        `Setting ${key}: the ${human} table is not a valid JSON array — repair it in Painting Settings or quantity discounts price as 1x`);
      continue;
    }
    tiers.forEach((row, rowIdx) => {
      const where = `Setting ${key} row ${rowIdx + 1}`;
      for (const [field, human2] of [["min_quantity", "minimum quantity"], ["max_quantity", "maximum quantity"]]) {
        if (row?.[field] !== undefined && row?.[field] !== null
          && (paintStrictNumber(row[field]) === null || paintStrictNumber(row[field]) < 0)) {
          add(key, "paint_labor_tier_row_unavailable",
            `${where}: record a finite, nonnegative ${human2} — the stored value dead-windows this tier`);
        }
      }
      if (row?.labor_multiplier !== undefined && row?.labor_multiplier !== null
        && (paintStrictNumber(row.labor_multiplier) === null || paintStrictNumber(row.labor_multiplier) < 0)) {
        add(key, "paint_labor_tier_row_unavailable",
          `${where}: record a finite, nonnegative labor multiplier — the stored value cannot price this tier`);
      }
    });
  }

  return issues;
}

// ---------- item-level scan ----------
// Consumed fields on each paint item. Issues hold the item's derived numbers
// (hold "item") — totals re-derive null because they sum held items.
const LETTER_SIZES = ["extra_small", "small", "normal", "medium", "large", "extra_large"];
const PRESENT = (v) => v !== undefined && v !== null;
// For this module a cleared stored value is malformed input, not an absent
// one: paintCalc's num("") launders to 0 / a clamp to 1 silently.
const nonnegField = (v) => paintStrictNumber(v) !== null && paintStrictNumber(v) >= 0;

export function paintItemIssues(rawItem = {}, index = 0) {
  const issues = [];
  const label = `Item ${index + 1}${rawItem?.description ? ` "${rawItem.description}"` : ""}`;
  const add = (field, code, message) =>
    issues.push(issue("paint", { index, itemIndex: index, field, code, message: `${label}: ${message}`, hold: "item" }));

  // item_type — every geometry branch keys on it; anything else prices a
  // silent $0 item.
  if (PRESENT(rawItem?.item_type) && !["panel", "lettering", "complex_shapes"].includes(rawItem.item_type)) {
    add("item_type", "paint_item_type_unavailable",
      "select Panel, Lettering, or Complex Shape — the stored type prices as $0 silently");
  }
  const effectiveType = rawItem?.item_type || "panel";

  // thickness — the strict imperial parse: malformed text used to vanish into
  // 0 (edge area silently dropped; "-1" even laundered to +1). Panel math has
  // an explicit edge-less branch so a real 0 is tolerated there; lettering
  // and complex shapes price nothing at all without a positive thickness.
  if (rawItem?.thickness !== undefined) {
    const t = paintThicknessNumber(rawItem.thickness);
    if (t === null || t < 0) {
      add("thickness", "paint_thickness_unavailable",
        "record a usable thickness (inches, e.g. 1/2 or 1-1/4) — the stored value silently drops edge pricing");
    } else if (t === 0 && effectiveType !== "panel") {
      add("thickness", "paint_thickness_unavailable",
        "record a positive thickness — lettering and complex shapes price nothing at 0\"");
    }
  }

  // length / width — every branch gates > 0; blank, zero, negative or
  // malformed dimensions silently collapse the item's paint and labor.
  for (const field of ["length", "width"]) {
    const n = paintStrictNumber(rawItem?.[field]);
    if (n === null || n <= 0) {
      add(field, "paint_dimension_unavailable",
        `record a positive, finite ${field === "length" ? (effectiveType === "lettering" ? "letter count" : "length") : (effectiveType === "lettering" ? "letter height" : "width")} (inches) — a blank or zero dimension prices the item as $0 silently`);
    }
  }

  // quantity — lettering forces 1 by design; other types clamp <1 to 1 in the
  // math, so a recorded 0/blank/malformed value silently repriced as one.
  if (effectiveType !== "lettering" && PRESENT(rawItem?.quantity)) {
    const q = paintStrictNumber(rawItem.quantity);
    if (q === null || q < 1) {
      add("quantity", "paint_quantity_unavailable",
        "record a quantity of 1 or more — a blank or malformed value prices as 1 silently");
    }
  }

  // paint_sides — the stored value chooses the multiplier branch; "none" is a
  // tolerated legacy alias for one_side.
  if (PRESENT(rawItem?.paint_sides) && rawItem.paint_sides !== ""
    && !["one_side", "both_sides", "none"].includes(rawItem.paint_sides)) {
    add("paint_sides", "paint_sides_unavailable",
      "choose One side or Both sides — the stored value silently prices as one side");
  }

  // edge complexity — complex-shape edge multiplier; negative values priced
  // negative edge area, malformed text repriced as 1x, blank as 0 edges.
  if (effectiveType === "complex_shapes" && PRESENT(rawItem?.edge_complexity_multiplier)
    && !nonnegField(rawItem.edge_complexity_multiplier)) {
    add("edge_complexity_multiplier", "paint_edge_complexity_unavailable",
      "record a finite, nonnegative edge complexity multiplier — the stored value cannot price edges");
  }

  // paint mask sq ft — consumed when more than one color is selected; blank
  // or malformed text silently priced as no mask.
  if (PRESENT(rawItem?.paint_mask_sqft) && !nonnegField(rawItem.paint_mask_sqft)) {
    add("paint_mask_sqft", "paint_mask_sqft_unavailable",
      "record a finite, nonnegative paint mask area (sq ft) — the stored value drops mask pricing");
  }

  // fixed waste gallons / base supplies — recorded junk silently became 0.
  for (const [field, human] of [["fixed_waste_gallons", "fixed waste (gallons)"], ["base_supplies_cost", "base supplies cost ($)"]]) {
    if (PRESENT(rawItem?.[field]) && !nonnegField(rawItem[field])) {
      add(field, field === "fixed_waste_gallons" ? "paint_fixed_waste_unavailable" : "paint_base_supplies_unavailable",
        `record a finite, nonnegative ${human} — the stored value silently became $0`);
    }
  }

  // letter_size — drives the complexity class for lettering only.
  if (effectiveType === "lettering" && PRESENT(rawItem?.letter_size) && rawItem.letter_size !== ""
    && !LETTER_SIZES.includes(rawItem.letter_size)) {
    add("letter_size", "paint_letter_size_unavailable",
      "the stored letter size is unsupported — it silently prices as moderate complexity");
  }

  // paint_colors — the math reads the array length verbatim (ported); a
  // non-array value normalized to [] silently bills no paint.
  if (PRESENT(rawItem?.paint_colors) && !Array.isArray(rawItem.paint_colors)) {
    add("paint_colors", "paint_colors_unavailable",
      "the stored color list is malformed — it silently bills $0 paint; re-add the colors");
  }

  return issues;
}

// ---------- project-level scan ----------
export function paintProjectInputIssues(project = {}) {
  const issues = [];
  const add = (field, code, message) =>
    issues.push(issue("paint", { field, code, message, hold: "project" }));

  // items must be an array — the calc maps it verbatim.
  if (project?.items !== undefined && !Array.isArray(project.items)) {
    add("items", "paint_items_unavailable",
      "the stored paint items are malformed — the project cannot be repriced");
  }

  // paint_supplies_per_sqft — blank/null laundered to $0 under num(); a
  // malformed string silently became the settings default. Explicit 0 stays a
  // legitimate free supplies rate.
  if (project?.paint_supplies_per_sqft !== undefined
    && (paintStrictNumber(project.paint_supplies_per_sqft) === null
      || paintStrictNumber(project.paint_supplies_per_sqft) < 0)) {
    add("paint_supplies_per_sqft", "paint_supplies_rate_unavailable",
      "record a finite, nonnegative supplies rate per sq ft — a blank or malformed value silently repriced supplies");
  }

  return issues;
}

// ---------- calc wrapper ----------
// Returns { calc, issues, held }. The calc keeps the real result shape; when
// held, every derived number a flagged input could have tainted is null —
// saved acknowledged totals on the record are the display fallback, never an
// invented $0. Raw rows are untouched.
const ITEM_HELD_FIELDS = ["supplies_cost", "paint_cost", "paint_gallons", "labor_hours", "labor_cost", "paintable_sqft"];

export function calcPaintingProject(project = {}, settings = {}) {
  const issues = [
    ...paintSettingIssues(settings),
    ...((Array.isArray(project?.items) ? project.items : [])
      .flatMap((item, index) => paintItemIssues(item, index))),
    ...paintProjectInputIssues(project),
  ];

  // A non-array items value is itself a project-level hold; hand the calc an
  // empty list so it still returns a real result shape (the input object is
  // never mutated — totals are nulled below regardless).
  const calcable = Array.isArray(project?.items) ? project : { ...project, items: [] };
  const calc = calculatePaintingProject(calcable, settings);
  const held = issues.length > 0;
  if (!held) {
    calc.__held = false;
    calc.pricingUnavailable = false;
    calc.issues = [];
    return { calc, issues, held };
  }

  const out = { ...calc, totals: { ...calc.totals } };
  const hasProjectHold = issues.some((i) => i.hold === "project");
  const itemHolds = new Set(issues.filter((i) => i.hold === "item").map((i) => i.itemIndex));

  // Held items keep their raw row but lose every derived number — the totals
  // sum those numbers so every aggregate is untrustworthy too.
  out.items = calc.items.map((item, index) => {
    if (!hasProjectHold && !itemHolds.has(index)) return item;
    const heldItem = { ...item };
    for (const field of ITEM_HELD_FIELDS) heldItem[field] = null;
    return heldItem;
  });
  for (const field of Object.keys(out.totals)) out.totals[field] = null;
  if (hasProjectHold) out.liquidPaintRate = null;

  out.__held = true;
  out.pricingUnavailable = true;
  out.issues = issues;
  return { calc: out, issues, held };
}

// ---------- UI helpers ----------
// Saved acknowledged pricing snapshot — only a real finite number counts.
// This is the gate for "Saved amounts (not current pricing)" display.
export const hasPaintCostSnapshot = (v) => typeof v === "number" && Number.isFinite(v);

// Blank-preserving input helper for number fields: "" stays "" so the input
// does not fight the user mid-typing; parseable text becomes a number;
// anything else stays raw so validation can flag it instead of laundering it
// into 0 (paintCalc's num("") silently read as 0 before).
export const paintDraftValue = (raw) => {
  if (raw === "") return "";
  const n = Number(raw);
  return Number.isFinite(n) ? n : raw;
};

// All issues attached to a single field (optionally a single item row).
export const issuesForField = (issues = [], field, itemIndex = null) =>
  issues.filter((i) => i.field === field && (itemIndex === null || i.itemIndex === itemIndex));
export const hasIssueFor = (issues = [], field, itemIndex = null) =>
  issuesForField(issues, field, itemIndex).length > 0;

